 batchStatic(){this.static.updateMatrixWorld(true);const groups=new Map();this.static.traverse(o=>{if(o.isMesh&&Object.values(this.geometries).includes(o.geometry)){const key=o.geometry.uuid+o.material.uuid;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(o);}});for(let arr of groups.values()){if(arr.length<3)continue;const inst=new THREE.InstancedMesh(arr[0].geometry,arr[0].material,arr.length);for(let [i,m]of arr.entries()){inst.setMatrixAt(i,m.matrixWorld);m.removeFromParent();}inst.receiveShadow=true;inst.castShadow=arr.some(m=>m.castShadow);this.scene.add(inst);}}
